int git_pkt_parse_ref(char **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref = NULL;
    char *msg = NULL;
    size_t ref_len, msg_len;
    int ret = -1;

    pkt = calloc(1, sizeof(*pkt));
    if (!pkt)
        return -1;

    if (len < 4 || memcmp(line, "ref ", 4) != 0) {
        free(pkt);
        return -1;
    }

    line += 4;
    len -= 4;

    // Parse the reference and message
    ref_len = strcspn(line, " ");
    ref = strndup(line, ref_len);
    if (!ref) {
        goto error;
    }

    line += ref_len + 1;
    len -= ref_len + 1;

    msg_len = len;
    msg = strndup(line, msg_len);
    if (!msg) {
        goto error;
    }

    pkt->type = GIT_PKT_REF;
    pkt->data = ref;
    pkt->msg = msg;

    *out = (char *)pkt;
    return 0;

error:
    free(pkt);
    free(ref);
    free(msg);
    return ret;
}

int git_pkt_parse_ref(char **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    size_t prefix_len = 0;

    if (len < 5) {
        return -1;
    }

    if (strncmp(line, "ref ", 4) == 0) {
        prefix_len = 4;
    } else if (strncmp(line, "symref ", 7) == 0) {
        prefix_len = 7;
    } else {
        return -1;
    }

    pkt = malloc(sizeof(*pkt));
    if (!pkt) {
        return -1;
    }

    pkt->type = GIT_PKT_REF;
    pkt->offset = prefix_len;
    pkt->len = len - prefix_len;
    pkt->data = malloc(pkt->len);
    if (!pkt->data) {
        free(pkt);
        return -1;
    }

    memcpy(pkt->data, line + prefix_len, pkt->len);

    *out = (char *)pkt;
    return 0;
}
